import datetime
from typing import Any, Dict, List, Optional
import uuid
from sqlalchemy import (
    CheckConstraint,
    Date,
    DateTime,
    Index,
    Integer,
    SmallInteger,
    Text,
    UniqueConstraint,
    func,
    text,
)
from sqlalchemy.dialects.postgresql import ARRAY, JSONB, UUID
from sqlalchemy.orm import Mapped, mapped_column
from app.db.session import Base


class Post(Base):
    __tablename__ = "posts"

    # Unique post identifier generated by PostgreSQL
    id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True),
        primary_key=True,
        server_default=text("gen_random_uuid()"),
    )

    # User ID from Neon Auth token (isolated per user, no foreign key)
    user_id: Mapped[str] = mapped_column(Text, nullable=False)

    # Local date the post is scheduled to go out in user timezone
    run_date: Mapped[datetime.date] = mapped_column(Date, nullable=False)

    # Post lifecycle status: starts as draft, then approved and published
    status: Mapped[str] = mapped_column(
        Text, nullable=False, server_default="draft"
    )

    # Chosen topic title and primary source URL
    topic_title: Mapped[str] = mapped_column(Text, nullable=False)
    topic_url: Mapped[str] = mapped_column(Text, nullable=False)

    # Candidate source articles used to research and ground the post
    sources: Mapped[List[Dict[str, Any]]] = mapped_column(JSONB, nullable=False)

    # LinkedIn post body text
    caption: Mapped[str] = mapped_column(Text, nullable=False)

    # Optional hashtags (0 to 3 items)
    hashtags: Mapped[List[str]] = mapped_column(
        ARRAY(Text), nullable=False, server_default=text("'{}'")
    )

    # Specs required to render the square image on demand
    image_spec: Mapped[Dict[str, Any]] = mapped_column(JSONB, nullable=False)

    # Scheduled publication timestamp in UTC (also serves as approval deadline)
    publish_at: Mapped[Optional[datetime.datetime]] = mapped_column(
        DateTime(timezone=True), nullable=True
    )

    # Audit tracking for LLM model and prompt template used
    llm_model: Mapped[str] = mapped_column(Text, nullable=False)
    prompt_version: Mapped[str] = mapped_column(Text, nullable=False)

    # Creation and update timestamps
    created_at: Mapped[datetime.datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=func.now()
    )
    updated_at: Mapped[datetime.datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=func.now()
    )

    # Source of approval decision (email, slack, dashboard) and decision timestamp
    approval_source: Mapped[Optional[str]] = mapped_column(Text, nullable=True)
    decided_at: Mapped[Optional[datetime.datetime]] = mapped_column(
        DateTime(timezone=True), nullable=True
    )

    __table_args__ = (
        CheckConstraint(
            "status IN ('draft', 'awaiting_approval', 'approved', 'rejected', 'publishing', 'published', 'failed', 'expired')",
            name="ck_posts_status",
        ),
        # Exactly one post per user per scheduled date
        UniqueConstraint("user_id", "run_date", name="uq_posts_user_id_run_date"),
        # Index for querying user post history sorted by creation time
        Index("ix_posts_user_id_created_at", "user_id", "created_at"),
    )


class GenerationRun(Base):
    __tablename__ = "generation_runs"

    # Unique run identifier generated by PostgreSQL
    id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True),
        primary_key=True,
        server_default=text("gen_random_uuid()"),
    )

    # User ID from Neon Auth token
    user_id: Mapped[str] = mapped_column(Text, nullable=False, index=True)

    # Local date for which content generation is running
    run_date: Mapped[datetime.date] = mapped_column(Date, nullable=False)

    # Run lifecycle status: started, succeeded, failed, or skipped
    status: Mapped[str] = mapped_column(Text, nullable=False)

    # Number of execution attempts for this run
    attempts: Mapped[int] = mapped_column(
        SmallInteger, nullable=False, server_default="1"
    )

    # Structured error code and short sanitized detail when failed
    error_code: Mapped[Optional[str]] = mapped_column(Text, nullable=True)
    error_detail: Mapped[Optional[str]] = mapped_column(Text, nullable=True)

    # Audit counters for search provider and external calls
    search_provider: Mapped[Optional[str]] = mapped_column(Text, nullable=True)
    search_calls: Mapped[int] = mapped_column(
        SmallInteger, nullable=False, server_default="0"
    )
    llm_calls: Mapped[int] = mapped_column(
        SmallInteger, nullable=False, server_default="0"
    )
    tokens_in: Mapped[int] = mapped_column(
        Integer, nullable=False, server_default="0"
    )
    tokens_out: Mapped[int] = mapped_column(
        Integer, nullable=False, server_default="0"
    )

    # ID of the generated draft post if successful
    post_id: Mapped[Optional[uuid.UUID]] = mapped_column(
        UUID(as_uuid=True), nullable=True
    )

    # Timestamps for run duration tracking
    started_at: Mapped[datetime.datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=func.now()
    )
    finished_at: Mapped[Optional[datetime.datetime]] = mapped_column(
        DateTime(timezone=True), nullable=True
    )

    __table_args__ = (
        CheckConstraint(
            "status IN ('started', 'succeeded', 'failed', 'skipped')",
            name="ck_generation_runs_status",
        ),
        # Single run record per user per scheduled date
        UniqueConstraint(
            "user_id", "run_date", name="uq_generation_runs_user_id_run_date"
        ),
    )
